class Base {
    int x = 2;
    Base() { System.out.print("P"); }
    int value() { return x * 2; }
    static String tag() { return "P"; }
}
class Child extends Base {
    int x = 5;
    Child() { System.out.print("C"); }
    @Override int value() { return x * 3; }
    static String tag() { return "C"; }
}
public class Main {
    public static void main(String[] args) {
        Base a = new Child();
        System.out.println("|" + a.x + "," + a.value() + "," + a.tag());
    }
}

