#include <stdio.h>
typedef struct Node { int v; struct Node *next; } Node;
int main(void) {
    Node a = {2, NULL}, b = {5, NULL}, c = {8, NULL};
    a.next = &c; c.next = &b;
    Node *head = &a;
    int t = head->v;
    head->v = head->next->v;
    head->next->v = t;
    Node *prev = head->next;
    Node *last = prev->next;
    prev->next = last->next;
    last->next = head;
    head = last;
    for (Node *p = head; p != NULL; p = p->next)
        printf("%d%s", p->v, p->next ? " " : "\n");
    return 0;
}

#include <stdio.h>
typedef struct N { int value; struct N *left, *right; } N;
int walk(N *n) {
    static int seen = 0;
    if (n == NULL) return 0;
    int left = walk(n->left);
    int right = walk(n->right);
    ++seen;
    printf("%d:%d ", seen, n->value);
    return n->value + left + right;
}
int main(void) {
    N leaf = {1, NULL, NULL};
    N left = {3, &leaf, NULL}, right = {6, NULL, NULL};
    N root = {10, &left, &right};
    int result = walk(&root);
    printf("\nsum=%d\n", result);
    return 0;
}

#include <stdio.h>
int main(void) {
    int data[] = {1, 2, 3, 4, 5, 6};
    int a[2][3] = {{0}};
    for (int i = 0; i < 6; ++i) {
        int j = (i + 1) % 6;
        a[j / 3][j % 3] = data[i];
    }
    int sum = 0;
    for (int i = 0; i < 6; ++i)
        sum += a[i / 3][i % 3] * (i % 2 == 0 ? 1 : -1);
    int *rows[] = {a[1], a[0]};
    printf("%d %d %d\n", a[0][0], a[0][1], a[0][2]);
    printf("%d %d %d\n", a[1][0], a[1][1], a[1][2]);
    printf("sum=%d, picked=%d\n", sum, **rows + rows[0][2]);
    return 0;
}

